func hexDec(s string) []byte {
  if s == "" {
    return nil
  }
  b, err := hex.DecodeString(s)
                 if err != nil { panic(err) }
  return b
}
func main(cur realm) {
  // Acknowledge the packet
  specs := ics23.IavlSpec()
