// Package market defines the minimal, vendor-neutral interface a GRC721
// collection must expose to become tradeable on the gnomarket marketplace
// realm (gno.land/r/gnomarket/nftmarket).
//
// There is no canonical GRC721 import path on gno.land — every collection
// vendors its own copy (gno.land/p/gnoswap/deps/grc721, gno.land/p/samcrew/grc721,
// hand-rolled implementations, etc.), each with its own nominally-typed
// TokenID. To stay usable by any of them without the marketplace importing a
// specific vendor's package, this interface is expressed entirely in plain
// `string`/`address` types rather than a shared TokenID type. A collection
// wires itself up with a small adapter (a handful of lines) translating its
// own TokenID type to/from string — see the package doc on NFT below for the
// expected shape.
package market

// NFT is the write surface a collection registers with the marketplace via
// RegisterCollection. It is safe to hand a value of this type to an
// untrusted realm (the marketplace) because TransferFrom is `cur realm`-typed:
// the implementation must derive its caller from cur.Previous() itself, never
// from a trusted-blindly argument. The gno VM enforces that a stashed/foreign
// `cur` cannot be replayed through interface dispatch (IsCurrent-strict on
// cross), so the marketplace holding this value can only ever move a token
// while it is genuinely the calling realm.
//
// This marketplace is non-custodial: a listed token never leaves the
// seller's wallet until the moment of sale. Instead, the seller grants the
// marketplace's own address approval (via the collection's normal
// Approve/SetApprovalForAll), and List/Buy only ever call TransferFrom —
// which succeeds because the collection's OWN authorization check (not
// marketplace-side trust) recognizes the marketplace as an approved
// operator, the same way it would recognize any other approved third party.
//
// A typical adapter, written once by a collection author on top of any
// vendored grc721 package (nft below is that package's concrete type, kept in
// an unexported var by the owning realm):
//
//	type marketAdapter struct{}
//
//	func (marketAdapter) Name() string { return "MyCollection" }
//	func (marketAdapter) OwnerOf(tid string) (address, error) {
//		return nft.OwnerOf(grc721.TokenID(tid))
//	}
//	func (marketAdapter) TokenURI(tid string) (string, error) {
//		return nft.TokenURI(grc721.TokenID(tid))
//	}
//	func (marketAdapter) GetApproved(tid string) (address, error) {
//		return nft.GetApproved(grc721.TokenID(tid))
//	}
//	func (marketAdapter) IsApprovedForAll(owner, operator address) bool {
//		return nft.IsApprovedForAll(owner, operator)
//	}
//	func (marketAdapter) TransferFrom(cur realm, from, to address, tid string) error {
//		caller := cur.Previous().Address()
//		return nft.TransferFrom(caller, from, to, grc721.TokenID(tid))
//	}
//
//	func RegisterWithMarketplace(cur realm) {
//		nftmarket.RegisterCollection(cross(cur), marketAdapter{})
//	}
//
// (nftmarket here refers to the stateful realm gno.land/r/gnomarket/nftmarket,
// which re-exports this package's NFT/Listing types — a collection adapter
// only needs to satisfy the method set below, not import this package at all.)
type NFT interface {
	// Name returns the collection's display name, for render purposes only.
	Name() string
	// OwnerOf returns the current owner of tid in the collection's own ledger.
	OwnerOf(tid string) (address, error)
	// TokenURI returns the token's metadata URI, for render purposes only.
	TokenURI(tid string) (string, error)
	// GetApproved returns the address explicitly approved to move tid, or
	// "" if none. The marketplace reads this (and IsApprovedForAll) before
	// accepting a listing, to verify the seller has actually granted it
	// permission — List does not itself grant or request anything.
	GetApproved(tid string) (address, error)
	// IsApprovedForAll reports whether operator holds blanket approval over
	// all of owner's tokens in this collection.
	IsApprovedForAll(owner, operator address) bool
	// TransferFrom moves tid from `from` to `to`. Implementations MUST derive
	// the effective caller from cur.Previous().Address() themselves and
	// apply their own collection's normal transfer authorization against it
	// — caller must be from's current owner, or an address from has
	// approved via Approve/SetApprovalForAll — never trust a caller
	// identity passed in some other way. This check, performed by the
	// collection itself rather than trusted from the marketplace, is what
	// makes it safe for the marketplace to move a seller's token without
	// ever holding it.
	TransferFrom(cur realm, from, to address, tid string) error
}

// Listing is a fixed-price sale order held by the marketplace. The token
// itself stays with Seller (approved to the marketplace, not escrowed)
// until Buy succeeds.
type Listing struct {
	CollectionID string // the registering realm's own PkgPath; spoof-proof
	TokenID      string
	Seller       address
	Price        int64 // ugnot
	CreatedAt    int64 // block height
}

// Package nftmarket is a fixed-price, non-custodial marketplace for any
// GRC721 collection whose owning realm registers a market.NFT adapter (see
// gno.land/p/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/market). It never imports a specific collection's
// package — collections come to it at runtime as registered interface
// values, so it can list and trade any compliant collection deployed by
// anyone, not just ones it was compiled against.
//
// Trade flow:
//  1. The collection realm calls RegisterCollection once, handing over an
//     adapter that satisfies market.NFT.
//  2. A seller approves this realm's own address on the collection (via the
//     collection's normal Approve or SetApprovalForAll) — no marketplace
//     involvement needed for that step, it's a plain GRC721 approval call.
//  3. The seller calls List, which verifies current ownership and approval
//     before accepting the listing. The token stays in the seller's wallet.
//  4. A buyer calls Buy with the exact price attached as ugnot. The realm
//     re-verifies ownership/approval are still valid (either could have
//     changed since List, since nothing was escrowed), moves the token
//     directly from seller to buyer in one call, then splits payment
//     between the seller and the platform fee recipient — effects before
//     interactions throughout, and the token or funds are never held by
//     this realm across more than one transaction.
package nftmarket

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/market"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

var (
	collections  = avl.NewTree() // collectionID (registrant's own PkgPath) -> market.NFT
	listings     = avl.NewTree() // listingKey -> *market.Listing
	listingOrder []string        // insertion order, for pagination/render

	admin *ownable.Ownable
)

// Fee is charged only on a completed Buy, taken out of the sale price
// (never added on top of it) and forwarded to whoever currently holds
// admin rights. FeeModePercent uses basis points (1/100 of a percent, e.g.
// 250 = 2.5%) — the same convention used elsewhere in the gno.land
// ecosystem for exactly this. maxFeeBps sanity-caps percent mode so a
// fat-fingered admin call can't accidentally set a predatory rate; flat
// mode is separately clamped to never exceed the sale price itself (see
// computeFee).
const (
	FeeModeFlat    = "flat"
	FeeModePercent = "percent"

	maxFeeBps = 5000 // 50% ceiling for FeeModePercent
)

var (
	feeMode        = FeeModeFlat
	feeValue int64 = 1_000_000 // 1 GNOT flat — testing default, see SetFee
)

func init() {
	// Deliberately left unset (empty owner) rather than derived from
	// cur.Previous() here: init() runs during package loading, before any
	// realistic MsgAddPackage-origin call frame exists to derive "who
	// deployed this" from — confirmed empty in practice, not just assumed.
	// ClaimAdmin below is the explicit, two-step way to establish it,
	// matching the ecosystem's own convention of treating the initial
	// admin as something set deliberately rather than inferred at init
	// time (e.g. memba_nft_v2's AdminAddress is a plain deploy-time
	// constant, not derived dynamically either).
	admin = ownable.NewWithAddress("")
}

// ClaimAdmin lets the caller become fee-governance admin — but only once,
// while no admin has been claimed yet. Call this yourself immediately
// after deploying this realm.
func ClaimAdmin(cur realm) {
	if admin.Owner() != "" {
		panic("admin already claimed")
	}
	admin = ownable.NewWithAddress(cur.Previous().Address())
}

func listingKey(collectionID, tid string) string {
	return collectionID + ":" + tid
}

func removeFromOrder(key string) {
	for i, k := range listingOrder {
		if k == key {
			listingOrder = append(listingOrder[:i], listingOrder[i+1:]...)
			return
		}
	}
}

func computeFee(price int64) int64 {
	if admin.Owner() == "" {
		return 0 // no one to receive a fee until ClaimAdmin is called
	}
	var fee int64
	switch feeMode {
	case FeeModePercent:
		fee = price * feeValue / 10_000
	default: // FeeModeFlat
		fee = feeValue
	}
	if fee > price {
		fee = price // never charge more than the sale itself
	}
	if fee < 0 {
		fee = 0
	}
	return fee
}

// Admin returns the current fee-governance admin address.
func Admin() address {
	return admin.Owner()
}

// GetFee returns the current fee mode ("flat" or "percent") and value
// (ugnot for flat, basis points for percent).
func GetFee() (mode string, value int64) {
	return feeMode, feeValue
}

// EstimateFee returns the fee that would be charged on a sale at price
// under the current fee configuration — for frontends to display before
// a Buy.
func EstimateFee(price int64) int64 {
	return computeFee(price)
}

// SetFee changes the fee mode/value. Admin-only.
func SetFee(cur realm, mode string, value int64) {
	admin.AssertOwnedBy(cur.Previous().Address())
	if mode != FeeModeFlat && mode != FeeModePercent {
		panic(`fee mode must be "flat" or "percent"`)
	}
	if value < 0 {
		panic("fee value must not be negative")
	}
	if mode == FeeModePercent && value > maxFeeBps {
		panic(ufmt.Sprintf("percent fee capped at %d bps (%d%%)", maxFeeBps, maxFeeBps/100))
	}
	feeMode = mode
	feeValue = value
}

// TransferAdmin hands fee governance to a new address. Admin-only.
func TransferAdmin(cur realm, newAdmin address) {
	if err := admin.TransferOwnership(0, cur, newAdmin); err != nil {
		panic(err.Error())
	}
}

// RegisterCollection lets a collection realm register its market.NFT adapter.
// Must be called by the collection realm itself, crossing (cross(cur) from the
// collection's own registration function) — collectionID is derived from the
// caller's own PkgPath so no other realm can register under, or overwrite, a
// collection identity that isn't its own.
func RegisterCollection(cur realm, nft market.NFT) string {
	collectionID := cur.Previous().PkgPath()
	if collectionID == "" {
		panic("RegisterCollection must be called by a realm, not a direct user transaction")
	}
	collections.Set(collectionID, nft)
	return collectionID
}

func mustCollection(collectionID string) market.NFT {
	nft, ok := collections.Get(collectionID).(market.NFT)
	if !ok {
		panic("unregistered collection: " + collectionID)
	}
	return nft
}

func getListing(key string) (*market.Listing, bool) {
	l, ok := listings.Get(key).(*market.Listing)
	return l, ok
}

func isApproved(nft market.NFT, owner, marketAddr address, tid string) bool {
	approved, err := nft.GetApproved(tid)
	if err != nil {
		panic(err.Error())
	}
	return approved == marketAddr || nft.IsApprovedForAll(owner, marketAddr)
}

// IsRegistered reports whether collectionID has a registered adapter.
func IsRegistered(collectionID string) bool {
	return collections.Has(collectionID)
}

// RegisteredCollectionsCount returns the number of registered collections.
func RegisteredCollectionsCount() int {
	return collections.Size()
}

// GetRegisteredCollectionsPage returns a page of registered collections, one
// per line: collectionID|displayName. These are the only collections a
// seller can actually list here — for a frontend's sell-collection picker.
// Ordered by collectionID (the tree's natural key order); limit is clamped
// to [1, 100].
func GetRegisteredCollectionsPage(offset, limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	out := ""
	collections.IterateByOffset(offset, limit, func(key string, value any) bool {
		nft, ok := value.(market.NFT)
		if !ok {
			return false
		}
		out += key + "|" + nft.Name() + "\n"
		return false
	})
	return out
}

// MarketAddress returns this realm's own address — the address a seller
// must approve (via the collection's Approve or SetApprovalForAll) before
// calling List. The token itself never moves here.
func MarketAddress() address {
	return unsafe.CurrentRealm().Address()
}

// List creates a fixed-price listing for tid. PREREQUISITE: the caller must
// currently own tid AND have approved this marketplace's address on the
// collection (Approve or SetApprovalForAll) — List only verifies and
// records the sale terms, it never moves the token.
func List(cur realm, collectionID, tid string, price int64) {
	if price <= 0 {
		panic("price must be positive")
	}
	nft := mustCollection(collectionID)
	seller := cur.Previous().Address()

	owner, err := nft.OwnerOf(tid)
	if err != nil {
		panic(err.Error())
	}
	if owner != seller {
		panic("caller does not own this token")
	}

	marketAddr := cur.Address()
	if !isApproved(nft, seller, marketAddr, tid) {
		panic("marketplace is not approved to transfer this token — call Approve or SetApprovalForAll on the collection first")
	}

	key := listingKey(collectionID, tid)
	if listings.Has(key) {
		panic("already listed")
	}
	listings.Set(key, &market.Listing{
		CollectionID: collectionID,
		TokenID:      tid,
		Seller:       seller,
		Price:        price,
		CreatedAt:    runtime.ChainHeight(),
	})
	listingOrder = append(listingOrder, key)
}

// Cancel removes a listing. Only the original seller may cancel. Since the
// token was never escrowed, there's nothing to transfer back — this is
// pure bookkeeping. (A seller can equivalently just revoke the collection
// approval directly; Cancel exists so the marketplace's own listing state
// stays accurate without requiring that.)
func Cancel(cur realm, collectionID, tid string) {
	key := listingKey(collectionID, tid)
	l, ok := getListing(key)
	if !ok {
		panic("not listed")
	}
	if cur.Previous().Address() != l.Seller {
		panic("only the seller can cancel this listing")
	}
	listings.Remove(key)
	removeFromOrder(key)
}

// UpdatePrice changes the price of an existing listing. Only the seller may
// update it.
func UpdatePrice(cur realm, collectionID, tid string, newPrice int64) {
	if newPrice <= 0 {
		panic("price must be positive")
	}
	key := listingKey(collectionID, tid)
	l, ok := getListing(key)
	if !ok {
		panic("not listed")
	}
	if cur.Previous().Address() != l.Seller {
		panic("only the seller can update this listing")
	}
	l.Price = newPrice
}

// Buy purchases a listed token. The caller must send exactly the listing's
// price in ugnot with the transaction. Re-verifies the seller still owns
// the token and the marketplace is still approved (either could have
// changed since List, since nothing was ever escrowed) before moving
// anything — then moves the token straight from seller to buyer and
// splits payment between the seller and the fee recipient, atomically.
func Buy(cur realm, collectionID, tid string) {
	// Without this, an intermediary realm could call Buy on a user's behalf
	// and receive the token itself while funneling that user's ugnot as the
	// payment — AssertOriginCall keeps buyer identity and payment sender the
	// same account.
	runtime.AssertOriginCall()

	key := listingKey(collectionID, tid)
	l, ok := getListing(key)
	if !ok {
		panic("not listed")
	}
	buyer := cur.Previous().Address()
	if buyer == l.Seller {
		panic("cannot buy your own listing")
	}

	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != l.Price {
		panic(ufmt.Sprintf("payment must be exactly %d ugnot", l.Price))
	}

	nft := mustCollection(collectionID)
	owner, err := nft.OwnerOf(tid)
	if err != nil {
		panic(err.Error())
	}
	if owner != l.Seller {
		panic("seller no longer owns this token — listing is stale")
	}
	marketAddr := cur.Address()
	if !isApproved(nft, l.Seller, marketAddr, tid) {
		panic("seller has revoked the marketplace's approval — listing is stale")
	}

	// Effects before interactions.
	listings.Remove(key)
	removeFromOrder(key)

	if err := nft.TransferFrom(cross(cur), l.Seller, buyer, tid); err != nil {
		panic(err.Error())
	}

	fee := computeFee(l.Price)
	sellerProceeds := l.Price - fee
	stdBanker := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if sellerProceeds > 0 {
		stdBanker.SendCoins(marketAddr, l.Seller, chain.Coins{{"ugnot", sellerProceeds}})
	}
	if fee > 0 {
		stdBanker.SendCoins(marketAddr, admin.Owner(), chain.Coins{{"ugnot", fee}})
	}
}

// GetListing returns a listing by collection and token ID.
func GetListing(collectionID, tid string) (market.Listing, bool) {
	l, ok := getListing(listingKey(collectionID, tid))
	if !ok {
		return market.Listing{}, false
	}
	return *l, true
}

// ListingsCount returns the number of active listings.
func ListingsCount() int {
	return len(listingOrder)
}

// GetListingsPage returns a page of active listings, one per line, oldest
// first: collectionID|tokenID|seller|price. Intended for frontends — plain
// pipe-delimited text is trivial to parse client-side without a JSON
// encoder. limit is clamped to [1, 100].
func GetListingsPage(offset, limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	if offset < 0 || offset >= len(listingOrder) {
		return ""
	}
	end := offset + limit
	if end > len(listingOrder) {
		end = len(listingOrder)
	}
	out := ""
	for _, key := range listingOrder[offset:end] {
		l, ok := getListing(key)
		if !ok {
			continue
		}
		out += l.CollectionID + "|" + l.TokenID + "|" + l.Seller.String() + "|" + strconv.Itoa(int(l.Price)) + "\n"
	}
	return out
}

// TokenInfo queries a registered collection's own adapter for display info
// about one of its tokens — for render/frontend use, not part of the trade
// flow itself.
func TokenInfo(collectionID, tid string) (name string, tokenURI string, owner address) {
	nft := mustCollection(collectionID)
	name = nft.Name()
	tokenURI, _ = nft.TokenURI(tid)
	owner, _ = nft.OwnerOf(tid)
	return
}

package nftmarket

import (
	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	out := "# gnomarket\n\n"
	out += "A fixed-price, non-custodial NFT marketplace for any registered GRC721 collection.\n\n"
	out += ufmt.Sprintf("Registered collections: %d\n\n", collections.Size())
	out += ufmt.Sprintf("Active listings: %d\n\n", len(listingOrder))
	if feeMode == FeeModePercent {
		out += ufmt.Sprintf("Platform fee: %d bps (%d%%)\n\n", feeValue, feeValue/100)
	} else {
		out += ufmt.Sprintf("Platform fee: %d ugnot flat\n\n", feeValue)
	}

	if len(listingOrder) == 0 {
		out += "_No active listings._\n"
		return out
	}

	out += "| Collection | Token | Seller | Price (ugnot) |\n"
	out += "|---|---|---|---|\n"
	for _, key := range listingOrder {
		l, ok := getListing(key)
		if !ok {
			continue
		}
		out += ufmt.Sprintf("| %s | %s | %s | %d |\n", l.CollectionID, l.TokenID, l.Seller, l.Price)
	}
	return out
}

// Package testcollection is a minimal GRC721-like collection realm used to
// exercise gno.land/r/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/nftmarket's registration and non-custodial
// trade flow end to end. It also doubles as a concrete, minimal reference
// for how any collection — regardless of which vendored grc721 package it's
// built on, or a hand-rolled ledger like this one — wires up a market.NFT
// adapter, including standard Approve/SetApprovalForAll support. It is
// deliberately not a general-purpose GRC721 implementation otherwise (open
// mint, no rich metadata beyond what SetMetadata provides): keep those
// concerns in a real collection, not in this fixture.
package testcollection

import (
	"encoding/base64"
	"errors"

	"gno.land/p/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/market"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/nftmarket"
)

var (
	owners            = avl.NewTree() // tid -> address
	tokenURIs         = avl.NewTree() // tid -> string (data: URI, OpenSea-style JSON metadata)
	tokenApprovals    = avl.NewTree() // tid -> address (single-token approval)
	operatorApprovals = avl.NewTree() // "owner|operator" -> bool (blanket approval)
)

const (
	collectionName   = "Test Collection"
	collectionSymbol = "GTC"
)

// Name, Symbol, and TokenCount are plain package-level functions (not
// methods on an internal object) specifically so a generic chain scanner —
// like gnomarket's own Collections/NFTs browser pages, or anyone else's —
// can call them directly via vm/qeval on this collection's own path,
// without needing to know an exported variable name to call a method on.
func Name() string      { return collectionName }
func Symbol() string    { return collectionSymbol }
func TokenCount() int64 { return int64(owners.Size()) }

var placeholderColors = []string{"steelblue", "seagreen", "indianred", "goldenrod", "mediumorchid", "darkslategray"}

// buildMetadataURI returns a self-contained data: URI JSON metadata blob
// (OpenSea metadata shape) whose image is itself an inline data: URI SVG —
// no network fetch needed to display it. Both are base64-encoded: a data:
// URI's payload must otherwise be percent-encoded for any character outside
// a narrow safe set, and this fixture has no URL-encoder handy, so base64
// sidesteps that entirely rather than risk producing an invalid URI.
func buildMetadataURI(tid, name string) string {
	sum := 0
	for _, b := range []byte(tid) {
		sum += int(b)
	}
	color := placeholderColors[sum%len(placeholderColors)]
	svg := ufmt.Sprintf(
		`<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'><rect width='300' height='300' fill='%s'/><text x='150' y='150' font-size='28' fill='white' text-anchor='middle' dy='.3em' font-family='sans-serif'>%s</text></svg>`,
		color, name,
	)
	image := "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
	metadata := ufmt.Sprintf(`{"name":"%s","description":"gnomarket test collection","image":"%s"}`, name, image)
	return "data:application/json;base64," + base64.StdEncoding.EncodeToString([]byte(metadata))
}

// SetMetadata sets (or overwrites) tid's display name/image. Open to any
// caller — this is a test fixture, not a real collection's admin surface.
func SetMetadata(cur realm, tid, name string) {
	if !owners.Has(tid) {
		panic(errNoSuchToken.Error())
	}
	tokenURIs.Set(tid, buildMetadataURI(tid, name))
}

var (
	errNoSuchToken   = errors.New("no such token")
	errNotAuthorized = errors.New("caller is not the owner or an approved operator")
)

// Mint is an open, unrestricted mint — fine for a test fixture, never do
// this in a real collection.
func Mint(cur realm, to address, tid string) {
	if owners.Has(tid) {
		panic("token already exists: " + tid)
	}
	owners.Set(tid, to)
}

func OwnerOf(tid string) (address, error) {
	owner, ok := owners.Get(tid).(address)
	if !ok {
		return "", errNoSuchToken
	}
	return owner, nil
}

func TokenURI(tid string) (string, error) {
	if !owners.Has(tid) {
		return "", errNoSuchToken
	}
	uri, _ := tokenURIs.Get(tid).(string)
	return uri, nil
}

func operatorKey(owner, operator address) string {
	return owner.String() + "|" + operator.String()
}

// Approve grants `to` permission to transfer tid on the caller's behalf.
// Caller must be tid's current owner.
func Approve(cur realm, to address, tid string) {
	caller := cur.Previous().Address()
	owner, ok := owners.Get(tid).(address)
	if !ok {
		panic(errNoSuchToken.Error())
	}
	if caller != owner {
		panic(errNotAuthorized.Error())
	}
	tokenApprovals.Set(tid, to)
}

// GetApproved returns the address currently approved to move tid, or ""
// if none.
func GetApproved(tid string) (address, error) {
	if !owners.Has(tid) {
		return "", errNoSuchToken
	}
	approved, _ := tokenApprovals.Get(tid).(address)
	return approved, nil
}

// SetApprovalForAll grants or revokes blanket approval for operator over
// all of the caller's tokens in this collection — this is what a seller
// calls to approve the marketplace once, rather than approving each token
// individually.
func SetApprovalForAll(cur realm, operator address, approved bool) {
	caller := cur.Previous().Address()
	key := operatorKey(caller, operator)
	if approved {
		operatorApprovals.Set(key, true)
	} else {
		operatorApprovals.Remove(key)
	}
}

// IsApprovedForAll reports whether operator holds blanket approval over
// all of owner's tokens in this collection.
func IsApprovedForAll(owner, operator address) bool {
	return operatorApprovals.Has(operatorKey(owner, operator))
}

// transfer is the single internal authorization+mutation path shared by
// Transfer, TransferFrom, and the marketplace adapter below. Authorizes the
// caller if they're the token's current owner, hold a single-token
// approval for it, or hold blanket operator approval from the owner — this
// three-way check is what lets an approved third party (like a
// marketplace) move a token the owner never transferred to them. Clears
// any single-token approval on success, since it shouldn't carry over to
// a new owner.
func transfer(caller, from, to address, tid string) error {
	owner, ok := owners.Get(tid).(address)
	if !ok {
		return errNoSuchToken
	}
	if owner != from {
		return errNotAuthorized
	}
	approved, _ := tokenApprovals.Get(tid).(address)
	if caller != owner && caller != approved && !IsApprovedForAll(owner, caller) {
		return errNotAuthorized
	}
	owners.Set(tid, to)
	tokenApprovals.Remove(tid)
	return nil
}

// TransferFrom moves tid from `from` to `to`. Caller must be from's current
// owner, or an address from has approved via Approve or SetApprovalForAll
// — the standard entrypoint any approved third party (including the
// marketplace) uses.
func TransferFrom(cur realm, from, to address, tid string) {
	caller := cur.Previous().Address()
	if err := transfer(caller, from, to, tid); err != nil {
		panic(err.Error())
	}
}

// Transfer sends the caller's own token to `to`. Convenience sugar for
// TransferFrom where from is the caller themselves.
func Transfer(cur realm, to address, tid string) {
	caller := cur.Previous().Address()
	if err := transfer(caller, caller, to, tid); err != nil {
		panic(err.Error())
	}
}

// marketAdapter satisfies market.NFT on top of this collection's own ledger.
// TransferFrom derives its caller from cur.Previous() itself, per market.NFT's
// contract, rather than trusting an argument — see gno.land/p/g1jkkpd3jyzzn8zz0jd8tmzewxxq9ysn67nhc35z/market
// for why that's what makes it safe to hand to an untrusted marketplace realm:
// the marketplace can only ever move a token it has genuinely been approved
// for, exactly as this same authorization check would treat any other
// approved third party.
type marketAdapter struct{}

func (marketAdapter) Name() string                        { return Name() }
func (marketAdapter) OwnerOf(tid string) (address, error) { return OwnerOf(tid) }
func (marketAdapter) TokenURI(tid string) (string, error) { return TokenURI(tid) }
func (marketAdapter) GetApproved(tid string) (address, error) {
	return GetApproved(tid)
}
func (marketAdapter) IsApprovedForAll(owner, operator address) bool {
	return IsApprovedForAll(owner, operator)
}
func (marketAdapter) TransferFrom(cur realm, from, to address, tid string) error {
	caller := cur.Previous().Address()
	return transfer(caller, from, to, tid)
}

var _ market.NFT = marketAdapter{}

// RegisterWithMarketplace registers this collection with the gnomarket
// marketplace. Callable by anyone since it only ever hands over a value
// whose TransferFrom re-derives and re-checks the caller itself — the
// marketplace still can't move a token it hasn't genuinely been approved
// for, see market.NFT's doc comment.
func RegisterWithMarketplace(cur realm) string {
	return nftmarket.RegisterCollection(cross(cur), marketAdapter{})
}
